        ...TUI_DEFAULT_NUMBER_FORMAT,
        ...settings,
        minimumFractionDigits,
        maximumFractionDigits: withTrailingZeroes
            ? maximumFractionDigits
            : Math.max(minimumFractionDigits, fractionPart.replace(/0*$/, '').length),
